import { test } from 'node:test';
import assert from 'node:assert/strict';
import { formatarUsuario, iniciais } from './solution.mjs';

test('formatarUsuario monta a frase com a ficha completa', () => {
  assert.equal(formatarUsuario({ nome: 'Ana', idade: 15, cidade: 'São Paulo' }), 'Ana tem 15 anos e mora em São Paulo.');
});

test('formatarUsuario usa o padrão quando a cidade não existe', () => {
  assert.equal(formatarUsuario({ nome: 'Bruno', idade: 17 }), 'Bruno tem 17 anos e mora em algum lugar.');
});

test('iniciais junta a primeira letra do nome e do sobrenome', () => {
  assert.equal(iniciais({ nome: 'Ana', sobrenome: 'Souza' }), 'AS');
});

test('iniciais sem sobrenome devolve só a inicial do nome', () => {
  assert.equal(iniciais({ nome: 'Bruno' }), 'B');
});

solutionCode:
export function formatarUsuario(usuario) {
  const { nome, idade, cidade = 'algum lugar' } = usuario;
  return `${nome} tem ${idade} anos e mora em ${cidade}.`;
}

export function iniciais(usuario) {
  const { nome, sobrenome = '' } = usuario;
  return `${nome.slice(0, 1)}${sobrenome.slice(0, 1)}`;
}
